const alerts = Array.isArray($json.alerts)
  ? $json.alerts
  : [];

if (alerts.length === 0) {
  return [{
    json: {
      has_alert: false,
      alert_count: 0,
      message: ""
    }
  }];
}

// ================================================
// HELPERS
// ================================================

const rank = {
  CRITICAL: 2,
  WATCH: 1,
  NORMAL: 0
};

function num(value) {
  if (value == null) return "-";
  return Number(value).toLocaleString("id-ID");
}

function pct(value) {
  if (value == null) return "-";
  return Number(value).toFixed(2) + "%";
}

function hours(value) {
  if (value == null) return "-";
  return Number(value).toFixed(2) + " jam";
}

function icon(status) {
  if (status === "CRITICAL") return "🔴";
  if (status === "WATCH") return "🟠";
  return "🟢";
}

function unhealthy(status) {
  return ["WATCH", "CRITICAL"].includes(status);
}

const components = [
  {
    key: "REVENUE",
    label: "Pendapatan",
    field: "revenue_status"
  },
  {
    key: "SELLER",
    label: "Seller",
    field: "seller_status"
  },
  {
    key: "PARCEL",
    label: "Paket di DP",
    field: "parcel_status"
  },
  {
    key: "DELIVERY",
    label: "Pengiriman",
    field: "delivery_status"
  }
];

// ================================================
// ONE MESSAGE PER CRITICAL DROP POINT
// ================================================

return alerts.map(a => {

  const manager = a.manager_name ?? "-";

  const responsibilities =
    Array.isArray(a.responsibility)
      ? a.responsibility
      : [];

  const reasons =
    Array.isArray(a.reasons)
      ? a.reasons
      : [];

  const problems = components
    .map(c => ({
      ...c,
      status: a[c.field]
    }))
    .filter(c => unhealthy(c.status))
    .sort(
      (x, y) =>
        (rank[y.status] ?? 0) -
        (rank[x.status] ?? 0)
    );

  const lines = [
    "🚨 CRITICAL OPERATIONAL ALERT",
    "",
    `🔴 ${a.drop_point_name} - CRITICAL`,
    `Perubahan: ${a.previous_status ?? "UNKNOWN"} → CRITICAL`,
    `Manager: ${manager}`,
    ""
  ];

  // ==============================================
  // COMPONENT DETAILS
  // ==============================================

  for (const problem of problems) {

    lines.push(
      `${icon(problem.status)} ${problem.label} - ${problem.status}`
    );

    switch (problem.key) {

      case "REVENUE":
        lines.push(
          `Pencapaian: ${pct(a.revenue_achievement_pct)}`,
          `Expected: ${pct(a.expected_achievement_pct)}`,
          `Gap: ${pct(a.revenue_gap_pct)}`
        );
        break;

      case "SELLER":
        lines.push(
          `Normal: ${num(a.normal_seller)}`,
          `Watch: ${num(a.watch_seller)}`,
          `Critical: ${num(a.critical_seller)}`,
          `Total monitored: ${num(a.total_monitored_seller)}`
        );
        break;

      case "PARCEL":
        lines.push(
          `Di DP: ${num(a.parcel_at_dp)}`,
          `>24 jam: ${num(a.parcel_over_24h)}`,
          `Paket terlama: ${hours(a.oldest_parcel_hours)}`,
          `Rata-rata di DP: ${hours(a.avg_dp_hours)}`,
          `Persentase keluar: ${pct(a.parcel_out_pct)}`
        );
        break;

      case "DELIVERY":
        lines.push(
          `On-time: ${pct(a.on_time_rate_pct)} vs SLA ${pct(a.delivery_sla_target_pct)}`,
          `Late: ${num(a.late_delivery)}`,
          `Failed: ${num(a.failed_delivery)}`,
          `Return: ${num(a.returned_delivery)}`,
          `Overdue: ${num(a.overdue_delivery)}`
        );
        break;
    }

    // Actual responsibility data from API.
    const owner = responsibilities.find(
      r => r.component === problem.key
    );

    if (owner) {
      lines.push(
        `Unit: ${owner.responsible_unit_name ?? "-"}`,
        `PIC: ${owner.responsible_staff_name ?? "-"}`
      );
    } else {
      lines.push(
        "Penanggung jawab: belum tersedia di mapping"
      );
    }

    lines.push("");
  }

  // ==============================================
  // CRITICAL REASONS
  // ==============================================

  if (reasons.length > 0) {
    lines.push("⚠️ Penyebab CRITICAL");

    reasons.forEach((reason, index) => {
      lines.push(`${index + 1}. ${reason}`);
    });

    lines.push("");
  }

  // ==============================================
  // ESCALATION
  // ==============================================

  lines.push(
    "👤 Eskalasi",
    `Drop Point Manager: ${manager}`,
    "",
    "🎯 Tindak Lanjut",
    "1. Tangani komponen CRITICAL terlebih dahulu.",
    "2. PIC unit terkait melakukan investigasi dan tindak lanjut.",
    "3. Manager memantau penyelesaian serta eskalasi hambatan."
  );

  return {
    json: {
      has_alert: true,
      alert_count: alerts.length,
      drop_point_id: a.drop_point_id,
      previous_status: a.previous_status,
      current_status: a.current_status,
      message: lines.join("\n")
    }
  };
});
